    cv: { label: 'Curriculum vitae', title: 'Luis Guinea', role: 'Music producer · A&R · AI systems & automation', location: 'Valencia, Spain', profileText: 'I work where creative and analytical thinking meet. For 10+ years I have been inside the music business as a label founder, A&R and producer; in parallel I build data systems and automations that turn messy information into decisions. I also manage and produce cultural projects and events, coordinating budgets, suppliers, contracts and logistics. Today that work centres on AI systems: multi-agent workflows across Claude, Codex and Gemini, custom agents and MCP integrations built for real business operations.', jazztoneRole: 'Music Producer', jazztone: 'Produce and arrange for independent artists across Latin jazz and pop; compose for film and advertising.', santoDate: 'Feb 2025 – Present', santoRole: 'Co-founder', santo: 'Brand and launch strategy, AI-produced visuals, social content and Meta Ads campaigns, CRM and automated promotional workflows; cultural production and organisation of Mexican tradition events for 150+ people, coordinating suppliers, setup, logistics and budgets.', botanasRole: 'Information Technology & Automation Developer · Grupo Botanas', botanas: 'Built IT, data and AI systems: LedgerApp, connected to AI assistants through MCP; a real-time transaction pipeline on AWS EC2 with automated reporting; Dispra, my own digital signage platform, deployed at Grupo Botanas; POS and QR-based digital menus; social-media and NFC review workflows.', peermusicRole: 'A&R / Admin Intern · Peermusic Spain', peermusic: 'Catalogue administration, licensing approvals, Python and SQL analysis.', tipazoRole: 'A&R Manager · Tipazo Music Group', tipazo: 'Oversaw 20 releases with Sony Music’s A&R team.', filmRole: 'Composer, additional music · Feature films', film: 'Additional music for four Mexican feature films: Las Vocales and Atrapadas en Familia (ViX+), Navidad en Vivo (HBO Max) and Infelices para Siempre (cinemas, Videocine). Scores by Juan Carlos Enríquez and Pablo Delgado.', mandalaDate: 'Jul 2021 – Jun 2023', mandalaRole: 'Music Director & Keyboardist', mandala: 'Directed an 11-piece ensemble: arrangements, scores, show assembly and live performances; transcribed music and produced demos and live-recorded medleys.', parvinDate: 'Jun 2021 – Jul 2022', parvinRole: 'Key Account Brand Manager', parvin: 'Liaised with LANDIA for the “La Villita” television advertisement, working directly with Cinta Negra Music, the music producer and marketing team; coordinated pre-production and recording sessions, contracts and delivery deadlines.', moctezumaRole: 'Founder & Label Director', moctezuma: 'Launched and marketed 50+ artists in Mexico, reaching 10M+ streams; planned campaigns, concerts and tours, including budgets, suppliers, contracting and logistics.', maDegree: 'MA', baDegree: 'BA', studies: '(studies)', maField: 'Global Entertainment and Music Business', musicProductionField: 'Music Production', communicationField: 'Communication and Digital Media', researchLabel: 'Research & writing', research: 'Data journalism, case studies and source verification.', dataLabel: 'Data & technology', data: 'Python, SQL, REST APIs and ETL pipelines; Chartmetric, Power BI, Tableau, Excel and Google Analytics; AWS (EC2), Next.js and Supabase.', aiLabel: 'AI & automation', ai: 'Multi-agent orchestration across Claude, Codex and Gemini; custom agents and Claude skills; MCP; prompt and context design; AI image generation from brand systems.', musicLabel: 'Music', music: 'Production, composition, arrangement, music direction.', instrumentsLabel: 'Multi-instrumentalist', instruments: 'Piano, keyboards and synthesizers; drums and percussion; guitar and bass; flute, accordion and trumpet.', softwareLabel: 'Music & visual software', software: 'Pro Tools, Logic Pro X, Ableton Live, Sibelius, Final Cut Pro, Photoshop, Illustrator.', languagesLabel: 'Languages', languages: 'Spanish native, English fluent, French B2.', botanasDate: 'Jan 2024 – Present', jazztoneDate: '2026 – Present', download: 'Print / save as PDF', profile: 'Profile', systems: 'AI & Automation Systems', argosDate: '2026', argosTitle: 'Argos · Multi-agent orchestrator', argos: 'My own orchestrator, operated from Telegram: it assembles task-specific agent teams and dispatches work to Claude, Codex and Gemini.', ledgerDate: '2025 – 2026', ledgerTitle: 'LedgerApp · Grupo Botanas', ledger: 'Financial platform that pulls POS data from Last.app and centralises revenue, costs and margins across venues; connected to AI assistants through MCP, so performance is queried in conversation.', creativeDate: 'Hospitality', creativeTitle: 'AI creative direction and Dispra', creative: 'Brand and visual manuals built with AI first, then used to write the prompts for a separate image model. All the visuals on the screens of the three El Remedio venues and Santo Chilaquil were produced this way; they run, with music, on Dispra, my own digital signage platform.', remedioLink: 'El Remedio: identity, AI photography and landing page ↗', pipelineDate: '2024 – Present', pipelineTitle: 'Real-time data pipeline · Grupo Botanas', pipeline: 'Transaction data from the payment system loaded in real time into a SQL database on AWS EC2, with automated Python reporting on sales trends, loss prevention and forecasting.', analyticsDate: '2024', analyticsTitle: 'Music analytics automation · Peermusic Spain (internship)', analytics: 'Systems on the Chartmetric API that monitor artist analytics for label rosters and catalogues, with automated streaming reports and airplay tracking from radio stations in different parts of the world.', experience: 'Experience', education: 'Education', skills: 'Skills' },
